/**
 * County disaster-history policy constants.
 *
 * OpenFEMA is a live API (one call per refresh); NOAA Storm Events has no
 * query API, so its half is a static snapshot generated by
 * scripts/generate-storm-events-snapshot.mjs from the NCEI bulk CSV files.
 */
export const LAYER_ID = 'disaster-history';
export const DISASTER_HISTORY_REFRESH_MS = 24 * 60 * 60_000;
export const OPENFEMA_URL =
  'https://www.fema.gov/api/open/v2/DisasterDeclarationsSummaries' +
  "?$filter=state eq 'NJ' and designatedArea eq 'Cape May (County)'" +
  '&$top=100&$orderby=declarationDate desc' +
  '&$select=femaDeclarationString,disasterNumber,declarationType,' +
  'declarationDate,incidentType,declarationTitle,incidentBeginDate,' +
  'incidentEndDate,paProgramDeclared,iaProgramDeclared,hmProgramDeclared';
export const COUNTY_FIPS = '34009';
